        "summary": "مدیریت حافظه KV Cache شبیه سیستم‌عامل با بسته‌های پیجینگ حافظه مجازی غیرپیوسته.",
        "summary_en": "Managing KV Cache memory using virtual memory paging concepts with non-contiguous blocks.",
