        "summary": "استاندارد باز ابداعی Anthropic برای اتصال امن و یکنواخت عامل‌ها به ابزارها و دیتابیس‌ها.",
        "summary_en": "An open standard by Anthropic connecting AI agents to tools, files, and databases seamlessly.",
