        "fullAnswer": "MLflow شامل چهار ماژول اصلی است: Tracking برای ثبت متریم‌ها و لوس‌ها، Projects برای بسته‌بندی کد، Models برای فرمت ذخیره‌سازی، و Model Registry برای مدیریت نسخه مدل‌ها (Staging / Production).",
